import math

def cut_worms(target_worms, total_time):
    dp = [[0] * int(total_time * 2) for _ in range(target_worms + 1)]
    dp[0][0] = 1
    for i in range(1, target_worms + 1):
        for j in range(int(total_time * 2)):
            if j >= 1:
                dp[i][j] += dp[i][j - 1]
            if j >= 1 and j <= int(total_time * 2) - 1:
                dp[i][j] += dp[i - 1][j - 1]
    result = []
    time = 0
    while True:
        for i in range(int(total_time * 2)):
            if dp[target_worms][i] == 1:
                result.append((time + i * 0.5, [1], [0.5, 0.5]))
                target_worms -= 1
                if target_worms == 0:
                    return result
        time += 0.5

